Translate("esMX", "garek-bandarion", {
	title = "Garek Bandarion",
	subtitle = "El primer paladín renegado",
	found = "Recordado en Bandarion Keep",
	hint = [=[Busque la fortaleza de las colinas del oeste que lleva su nombre.]=],
	allegiance = [=[Renegados · Guardia de la muerte · antes la Guardia de la Ciudad de Lordaeron]=],
	aliases = { "Garek", "Capitán Bandarion" },
	sections = {
		{
			title = "Resumen",
			text = [=[Garek Bandarion fue un soldado de {link:lordaeron}Lordaeron{/link} que murió en su caída y se alzó entre los {link:forsaken}Renegados{/link}. Se convirtió en el primer capitán de la Guardia de la muerte, y fue el primero de los Renegados que abrazó la {link:holy-light}Luz Sagrada{/link} como paladín. Cayó cuando la necrópolis de {red:naxxramas}Naxxramas{/red} vino contra {link:undercity}Entrañas{/link}. Los paladines de {link:tyr-s-watch}Tyr's Watch{/link} dieron su nombre a su monasterio, y aún lo pronuncian como grito de batalla.]=],
		},
		{
			title = "Importancia",
			text = [=[Para los paladines renegados, Garek es la prueba de que la Luz no los abandonó en la muerte. Para la Guardia de la muerte, es el capitán que formó sus filas. Su vida une los últimos días del reino de los vivos con los primeros días del reino de los muertos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• En vida sirvió en la Guardia de la Ciudad de la capital a las órdenes del capitán Landen, que lo eligió como su sucesor.
• El día en que {link:arthas-menethil}Arthas{/link} asesinó a su padre, él y Landen sacaron a los supervivientes por las cloacas bajo la ciudad.
• Se vengó del barón Rivendare, el señor que traicionó al reino ante el {link:cult-of-the-damned}Culto de los Malditos{/link}, y murió de sus heridas y de la peste.
• Como Renegado, luchó junto a la forestal oscura {link:dark-ranger-anya}Anya{/link} en los primeros días de {link:undercity}Entrañas{/link}.
• Llegó a ser capitán de la Guardia de la muerte.
• Murió en la defensa de Entrañas contra Naxxramas.]=],
		},
	},
	chapters = {
		{
			title = "Los últimos días de Lordaeron",
			hint = [=[Averigüe lo que dicen los Renegados de Entrañas de su primer capitán.]=],
			text = [=[Garek era un joven guardia que ansiaba la batalla, y su capitán, Landen, le dijo que proteger al pueblo era la gloria mayor. La noche en que {link:arthas-menethil}Arthas{/link} mató al rey {link:terenas-menethil}Terenas Menethil{/link}, encontraron el salón del trono lleno de cultistas. {link:uther-the-lightbringer}Uther el Iluminado{/link} los envió a salvar a quienes pudieran. Bajo la ciudad descubrieron que el culto llevaba mucho tiempo preparado. Landen se quedó atrás para contener al barón Rivendare y que Garek pudiera llevar al pueblo a un lugar seguro. Garek nunca perdonó al barón. Le dio caza hasta Stratholme y lo mató allí, y murió de sus heridas.]=],
		},
		{
			title = "Una segunda vida",
			hint = [=[Escuche a los paladines de Bandarion Keep hablar de su fundador.]=],
			text = [=[Garek despertó en las criptas de {link:undercity}Entrañas{/link} sin más recuerdo que su nombre. El boticario Putress quería usar su cuerpo como piezas. La forestal oscura {link:dark-ranger-anya}Anya{/link} se lo impidió. Garek juró lealtad a {link:sylvanas-windrunner}Sylvanas{/link}, y con Anya reunió a los muertos con voluntad propia de entre las ruinas, despejó los túneles y ayudó a crecer a la ciudad. Cuando la {link:scarlet-crusade}Cruzada Escarlata{/link} atravesó las murallas de Entrañas, dirigió a la Guardia de la muerte contra ella. En algún momento de esos años, la Luz empezó a responderle de nuevo.]=],
		},
		{
			title = "La fortaleza de su nombre",
			hint = [=[Averigüe por qué la fortaleza de Northface Rock lleva su nombre.]=],
			text = [=[Cuando Naxxramas llegó a las ruinas de la capital, los {link:forsaken}Renegados{/link} y el {link:argent-dawn}Alba Argenta{/link} la combatieron juntos en la superficie. Garek no volvió. {link:danitha-morr}Danitha Morr{/link} y {link:leonid-barthalomew}Leonid Barthalomew{/link} lucharon en aquella batalla y perdieron allí a muchos amigos. Cuando Danitha tomó la vieja fortaleza de {link:bandarion-keep}Northface Rock{/link} para su orden, le dio el nombre de él.]=],
		},
	},
	mentions = {
		{ text = "Una causa justa" },
		{ text = "{link:bandarion-keep}Bandarion Keep{/link}" },
		{ text = "La justicia de la Luz" },
	},
	bonds = {
		{ id = "dark-ranger-anya", name = "Forestal oscura Anya", note = "su compañera" },
		{ id = "danitha-morr", name = "Danitha Morr", note = "dio su nombre a la fortaleza" },
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "un amigo" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "su reina" },
	},
})

Translate("esMX", "dark-ranger-anya", {
	title = "Forestal oscura Anya",
	subtitle = "Forestal oscura de la Reina alma en pena",
	found = "Desconocido en estos días",
	hint = [=[Conozca su historia a través de los relatos de Garek Bandarion.]=],
	allegiance = "Renegados · antes los Errantes de Quel'Thalas",
	aliases = { "Anya" },
	sections = {
		{
			title = "Resumen",
			text = [=[Anya es una forestal oscura, una de las elfas no-muertas que sirven a {link:sylvanas-windrunner}Sylvanas Windrunner{/link}. En vida fue forestal de {link:quel-thalas}Quel'Thalas{/link} a las órdenes de Sylvanas. Murió defendiendo su patria contra la {link:scourge}Plaga{/link} y se alzó como su esclava. Recuerda todo lo que hizo en ese tiempo. Cuando se liberó, Sylvanas le dio un lugar al que pertenecer, y por ello Anya entregó a la Dama Oscura su lealtad para siempre.]=],
		},
		{
			title = "Importancia",
			text = [=[Anya es una de las primeras forestales oscuras de los {link:forsaken}Renegados{/link}, y una de las que vieron surgir {link:undercity}Entrañas{/link} de los túneles. Fue la compañera de {link:garek-bandarion}Garek Bandarion{/link} en las primeras guerras del reino de los muertos. Donde él perdió sus recuerdos, ella conservó todos los suyos, y le enseñó que para muchos Renegados la muerte es borrón y cuenta nueva, y una segunda vida. Confía muy poco en los vivos. Cuando un paladín de la antigua Mano de Plata mostró clemencia a un trabajador renegado y su capitán mató al hombre de todos modos, Anya le dijo a Garek que los vivos nunca verían a los no-muertos como personas, y que no se podía confiar en ellos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Cayó en la defensa de {link:quel-thalas}Quel'Thalas{/link}, e hizo cosas terribles como esclava del Rey Exánime.
• Impidió que el boticario Putress despedazara a {link:garek-bandarion}Garek{/link} para usarlo como piezas cuando despertó.
• Le dijo a Garek que su memoria perdida era una misericordia, pues ella recordaba demasiado bien sus propios crímenes.
• Con Garek, rescató a los muertos con voluntad propia de las ruinas de la capital.
• Luchó a su lado contra la {link:scarlet-crusade}Cruzada Escarlata{/link} y contra Naxxramas.
• Con {link:sylvanas-windrunner}Sylvanas{/link} y la forestal oscura Clea, cabalgó hasta la {link:the-marris-stead}Hacienda de Marris{/link} en busca de {link:nathanos-blightcaller}Nathanos Marris{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de estos días registra dónde sirve Anya ahora, ni qué hizo después de la caída de {link:garek-bandarion}Garek{/link}.]=],
		},
	},
	bonds = {
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "su compañero" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "su reina" },
	},
})

Translate("esMX", "danitha-morr", {
	title = "Danitha Morr",
	subtitle = "Comandante de Bandarion Keep",
	found = "Bandarion Keep",
	hint = "Hable con la líder de los paladines de Bandarion Keep.",
	allegiance = "Tyr's Watch · Renegados",
	aliases = { "Danitha" },
	sections = {
		{
			title = "Resumen",
			text = [=[Danitha Morr dirige a los paladines de {link:tyr-s-watch}Tyr's Watch{/link} desde {link:bandarion-keep}Bandarion Keep{/link}. Se llama a sí misma lo más parecido a un comandante que tiene la fortaleza. Luchó en la defensa de {link:undercity}Entrañas{/link} cuando llegó Naxxramas, y allí perdió amigos, entre ellos {link:garek-bandarion}Garek Bandarion{/link}. Cuando tomó la fortaleza en ruinas de Northface Rock, le dio el nombre de él.]=],
		},
		{
			title = "Importancia",
			text = [=[Danitha intenta hacer lo que ningún Renegado ha hecho antes: formar una orden de la {link:holy-light}Luz Sagrada{/link} entre los muertos y ganarle un lugar en su reino. Su pueblo teme a los paladines. Su reina desconfía de ellos. Cree que la obra puede llevar décadas, y la hace de todos modos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Reconstruye {link:bandarion-keep}Bandarion Keep{/link} con materiales rescatados de las ruinas de {link:shadowvale}Shadowvale{/link}.
• Da caza a los Deslustrados, los paladines alzados que vuelven sus hojas contra los {link:forsaken}Renegados{/link}.
• Envía a sus paladines a ayudar a los pobres de {link:undercity}Entrañas{/link}.
• Envía a su orden a {link:silverpine-forest}Argénteos{/link} para ganarse la confianza de la {link:horde}Horda{/link}.]=],
		},
		{ title = "Sin registro", text = "Poco se ha escrito de la vida de Danitha antes de su muerte." },
	},
	chapters = {
		{
			title = "Un hogar en las colinas",
			hint = [=[Encuentre el camino a Bandarion Keep y conozca a su comandante.]=],
			text = [=[La fortaleza era una ruina cuando llegaron los paladines de Danitha. Los múrlocs Vile Fin la habían convertido en un lugar de desove, y luchaban por recuperarla incluso después de ser expulsados. Danitha tenía pocos materiales, menos aliados y muchísimos muros que reparar. Daba la bienvenida a cada recién llegado que aún se aferraba a la Luz.]=],
		},
		{
			title = "Los Deslustrados",
			hint = [=[Ocúpese de los paladines alzados que han hecho de Shadowvale su guarida.]=],
			text = [=[No todo paladín que se alza puede aceptar en qué se ha convertido. Algunos conservan los odios de sus viejas vidas y matan a los {link:forsaken}Renegados{/link} que encuentran. Cada una de esas muertes facilita a los enemigos de la orden avivar el miedo. Danitha hizo destruir a los Deslustrados de {link:shadowvale}Shadowvale{/link} y decapitar a su comandante, {link:rudolph-gelhardt}Rudolph Gelhardt{/link}.]=],
		},
		{
			title = "Una muestra de buena fe",
			hint = "Lleve el regalo de Danitha a la Dama Oscura.",
			text = [=[Danitha envió la cabeza de {link:rudolph-gelhardt}Gelhardt{/link} a {link:undercity}Entrañas{/link}, para mostrar a {link:sylvanas-windrunner}la Dama Oscura{/link} que {link:tyr-s-watch}Tyr's Watch{/link} pone orden en su propia casa. Sylvanas no dudó de la sinceridad de Danitha. Dijo que esperaba que más paladines enloquecieran, y que algún día podría decidir no tolerar más a la orden. Dijo a sus paladines que sirvieran bien, y que ella estaría vigilando.]=],
		},
	},
	mentions = {
		{ text = "Recorrer los terrenos" },
		{ text = "Los Deslustrados" },
		{ text = "Una muestra de buena fe" },
		{ text = "Una lección de divinidad" },
		{ text = "Incidente diplomático" },
		{ text = "Una causa justa" },
	},
	bonds = {
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "un amigo caído" },
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "un viejo camarada" },
		{ id = "rudolph-gelhardt", name = "Rudolph Gelhardt", note = "el comandante de los Deslustrados" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "desconfía de su orden" },
	},
})

