Translate("esMX", "rudolph-gelhardt", {
	title = "Rudolph Gelhardt",
	subtitle = "Comandante de los Deslustrados",
	found = "Shadowvale, en el Whispering Forest",
	hint = [=[Enfréntese al comandante de los Deslustrados en las ruinas de Shadowvale.]=],
	allegiance = "Los Deslustrados",
	aliases = { "Gelhardt" },
	sections = {
		{
